class Appointment { final int? id,customerId; final String title,startsAt,location,note; final int durationMinutes; final bool completed; const Appointment({this.id,this.customerId,required this.title,required this.startsAt,this.durationMinutes=60,this.location='',this.note='',this.completed=false}); factory Appointment.fromMap(Map<String,Object?>m)=>Appointment(id:m['id'] as int?,customerId:m['customer_id'] as int?,title:(m['title']??'') as String,startsAt:(m['starts_at']??'') as String,durationMinutes:(m['duration_minutes']??60) as int,location:(m['location']??'') as String,note:(m['note']??'') as String,completed:((m['completed']??0) as int)==1); }
